﻿import React from 'react';
import {AbsoluteFill, useS, en, fin, T, DUR, words, interpolate, clamp, Easing, golpe, sacudida, Paso, Textura, Profundidad, Brillo, Chip, Contador, Regla, Destello, Ondas, tono, h} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---------- tiempos: todo sale de las palabras ----------
const SC = words.map((w, i) => (w.f ? i : -1)).filter((i) => i >= 0).map((i) => T(i));
const E = (n: number) => SC[n - 1];
const ez = (s: number, a: number, b: number) => interpolate(s, [a, b], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
const eo = (s: number, a: number, b: number) => interpolate(s, [a, b], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const ei = (s: number, a: number, b: number) => interpolate(s, [a, b], [0, 1], {...clamp, easing: Easing.in(Easing.cubic)});
const pop = (s: number, a: number, d = 0.4) => interpolate(s, [a, a + d], [0, 1], {...clamp, easing: Easing.out(Easing.back(2))});
const lerp = (a: number, b: number, k: number) => a + (b - a) * k;
const sm = (x: number) => { const k = Math.max(0, Math.min(1, x)); return k * k * (3 - 2 * k); };

// ---------- gradientes (una sola luz: arriba a la izquierda) ----------
const Defs = () => (
  <defs>
    <linearGradient id="gSky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F6D898" /><stop offset="1" stopColor="#EDBF77" /></linearGradient>
    <linearGradient id="gTierra" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#D8B678" /><stop offset="1" stopColor="#B08549" /></linearGradient>
    <linearGradient id="gTierraO" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#A47E49" /><stop offset="1" stopColor="#5C4226" /></linearGradient>
    <linearGradient id="gBarro" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#B7A488" /><stop offset=".5" stopColor="#8C7B64" /><stop offset="1" stopColor="#5E513F" /></linearGradient>
    <linearGradient id="gMadera" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#C99B66" /><stop offset="1" stopColor="#7A5330" /></linearGradient>
    <linearGradient id="gHierro" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#CDD1D4" /><stop offset="1" stopColor="#687075" /></linearGradient>
    <linearGradient id="gPiel" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#EBC19B" /><stop offset="1" stopColor="#B98660" /></linearGradient>
    <linearGradient id="gBronce" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F6DD98" /><stop offset="1" stopColor="#B7832E" /></linearGradient>
    <linearGradient id="gPared" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#8E6D45" /><stop offset="1" stopColor="#3F2B18" /></linearGradient>
    <linearGradient id="gLuz" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFF1C4" stopOpacity=".5" /><stop offset="1" stopColor="#FFF1C4" stopOpacity="0" /></linearGradient>
    <radialGradient id="gHalo"><stop offset="0" stopColor="#FFF3CC" stopOpacity=".8" /><stop offset="1" stopColor="#FFE6A0" stopOpacity="0" /></radialGradient>
    <radialGradient id="gHoyo"><stop offset="0" stopColor="#0E0703" /><stop offset=".7" stopColor="#2B1A0C" /><stop offset="1" stopColor="#4B3217" /></radialGradient>
    <linearGradient id="gPasto" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#86B565" /><stop offset="1" stopColor="#3B6A3B" /></linearGradient>
  </defs>
);
const Svg: React.FC<{children: React.ReactNode}> = ({children}) => (
  <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', left: 0, top: 0}}>
    <Defs />
    {children}
  </svg>
);
const Acabado: React.FC<{sem: number; luz?: string; sombra?: string; prof?: string; lejos?: string}> = ({sem, luz = 'rgba(255,236,190,.22)', sombra = 'rgba(30,16,6,.55)', prof = 'rgba(40,22,8,.32)', lejos = 'rgba(255,235,190,.12)'}) => (
  <>
    <Textura tipo="fibra" base="transparent" linea="#e8d3a8" luz="#ffffff" semilla={sem} escala={0.5} opacidad={0.07} />
    <Profundidad color={prof} lejos={lejos} manchas={2} semilla={sem} deriva={0.3} />
    <Brillo x={330} y={430} r={520} color={luz} />
    <AbsoluteFill style={{background: `radial-gradient(ellipse at 50% 46%, transparent 52%, ${sombra} 100%)`}} />
  </>
);

// ---------- soldado de barro (frente) ----------
type Pal = {skin: string; hair: string; armor: string; robe: string; pant: string; belt: string; shoe: string; rivet: string; trim: string; line: string; lite: string; arm: string};
const CLAY: Pal = {skin: 'url(#gBarro)', hair: '#4E4333', armor: 'url(#gBarro)', robe: 'url(#gBarro)', pant: 'url(#gBarro)', belt: '#6B5C48', shoe: '#4A3F31', rivet: '#B7A488', trim: '#6B5C48', line: '#3B3126', lite: 'rgba(255,248,225,.4)', arm: '#8C7B64'};
const PINT: Pal = {skin: '#E2B089', hair: '#2B211B', armor: '#BE3A2E', robe: '#3D8D5B', pant: '#2E6FB7', belt: '#E1B14B', shoe: '#3A2A22', rivet: '#F1DDA0', trim: '#E1B14B', line: '#3B2A22', lite: 'rgba(255,255,255,.3)', arm: '#3D8D5B'};
const TINTA: Pal = {skin: '#BBA78B', hair: '#4A3F33', armor: '#AE9A7C', robe: '#B7A385', pant: '#9C8868', belt: '#7C6B52', shoe: '#5B4E3C', rivet: '#D6C7A6', trim: '#7C6B52', line: '#3A2F26', lite: 'rgba(255,250,235,.4)', arm: '#B7A385'};

const Soldado: React.FC<{x: number; y: number; k?: number; pal?: Pal; det?: boolean; lanza?: boolean; ink?: string; ojos?: number}> = ({x, y, k = 1, pal = CLAY, det = true, lanza = false, ink, ojos = 1}) => {
  const p = pal;
  const oy = Math.max(0.5, 3.6 * ojos);
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`} stroke={ink} strokeWidth={ink ? 3 : 0} strokeLinejoin="round">
      <ellipse cy="3" rx="74" ry="13" fill="rgba(40,25,10,.32)" stroke="none" />
      {lanza && (
        <g stroke="none">
          <rect x="78" y="-520" width="7" height="520" fill="#5A4630" />
          <path d="M81.5 -578 L93 -520 L70 -520Z" fill="url(#gBronce)" />
        </g>
      )}
      <path d="M-40 -150 L-34 -14 L-4 -14 L-2 -150Z" fill={p.pant} />
      <path d="M40 -150 L34 -14 L4 -14 L2 -150Z" fill={p.pant} />
      <path d="M-46 -16 L-2 -16 L2 3 L-54 3Z" fill={p.shoe} />
      <path d="M46 -16 L2 -16 L-2 3 L54 3Z" fill={p.shoe} />
      <path d="M-64 -252 L64 -252 L78 -118 L-78 -118Z" fill={p.robe} />
      {det && <path d="M-30 -250 L-38 -120 M0 -250 L0 -118 M30 -250 L38 -120" stroke={p.line} strokeOpacity=".25" strokeWidth="4" fill="none" />}
      <path d="M-68 -330 Q-98 -280 -84 -238" stroke={p.arm} strokeWidth="32" strokeLinecap="round" fill="none" />
      <path d="M68 -330 Q102 -290 92 -248" stroke={p.arm} strokeWidth="32" strokeLinecap="round" fill="none" />
      <circle cx="-82" cy="-226" r="15" fill={p.skin} />
      <circle cx="92" cy="-236" r="15" fill={p.skin} />
      <path d="M-60 -342 Q0 -358 60 -342 L68 -240 L-68 -240Z" fill={p.armor} />
      {det && (
        <g>
          <path d="M-63 -322 H63 M-65 -298 H65 M-67 -274 H67" stroke={p.line} strokeOpacity=".3" strokeWidth="3" fill="none" />
          {[-48, -24, 0, 24, 48].map((a) => [-310, -286, -262].map((b) => <circle key={a + '_' + b} cx={a} cy={b} r="3" fill={p.rivet} stroke="none" />))}
          <path d="M-60 -340 Q-70 -290 -66 -245" stroke={p.lite} strokeWidth="6" fill="none" />
        </g>
      )}
      <rect x="-70" y="-250" width="140" height="16" rx="4" fill={p.belt} />
      <rect x="-10" y="-252" width="20" height="20" rx="3" fill={p.trim} />
      <ellipse cx="-66" cy="-336" rx="26" ry="18" fill={p.armor} />
      <ellipse cx="66" cy="-336" rx="26" ry="18" fill={p.armor} />
      <rect x="-13" y="-366" width="26" height="30" fill={p.skin} />
      <ellipse cx="-30" cy="-392" rx="6" ry="11" fill={p.skin} />
      <ellipse cx="30" cy="-392" rx="6" ry="11" fill={p.skin} />
      <ellipse cx="0" cy="-394" rx="30" ry="37" fill={p.skin} />
      <ellipse cx="3" cy="-441" rx="14" ry="13" fill={p.hair} />
      <path d="M-31 -400 Q-34 -438 0 -441 Q34 -438 31 -400 Q20 -419 0 -421 Q-20 -419 -31 -400Z" fill={p.hair} />
      {det && (
        <g stroke="none">
          {[-12, 12].map((a) => (
            <g key={a}>
              <ellipse cx={a} cy="-396" rx="5.2" ry={oy} fill="#241A12" />
              {ojos > 0.5 && <circle cx={a + 1.8} cy="-397.6" r="1.6" fill="#fff" />}
            </g>
          ))}
          <path d="M-19 -405 Q-12 -409 -5 -405 M5 -405 Q12 -409 19 -405" stroke={p.line} strokeWidth="2.2" fill="none" />
          <path d="M0 -394 L3 -382 L-2 -382" stroke={p.line} strokeOpacity=".5" strokeWidth="2" fill="none" />
          <path d="M-14 -376 Q0 -382 14 -376 Q4 -372 0 -374 Q-4 -372 -14 -376Z" fill={p.hair} />
          <path d="M-6 -368 Q0 -366 6 -368" stroke={p.line} strokeWidth="2" fill="none" />
        </g>
      )}
    </g>
  );
};

// ---------- pala (protagonista): mango de madera, hoja de hierro ----------
const Pala: React.FC<{x: number; y: number; rot?: number; k?: number; len?: number}> = ({x, y, rot = 0, k = 1, len = 1500}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
    <rect x="-12" y={-len} width="24" height={len - 130} rx="9" fill="url(#gMadera)" />
    <rect x="-34" y={-len} width="68" height="22" rx="10" fill="url(#gMadera)" />
    <rect x="-7" y={-len + 30} width="4" height={len - 200} fill="rgba(255,255,255,.22)" />
    <path d="M-15 -150 H15 L13 -126 H-13Z" fill="#7B8186" />
    <path d="M-60 -130 Q-66 -20 0 26 Q66 -20 60 -130 Q0 -110 -60 -130Z" fill="url(#gHierro)" stroke="#4F5559" strokeWidth="4" />
    <path d="M-42 -116 Q-46 -48 -10 -8" stroke="rgba(255,255,255,.65)" strokeWidth="6" fill="none" strokeLinecap="round" />
  </g>
);

// ---------- campesino con sombrero de paja ----------
const Campesino: React.FC<{x: number; y: number; k?: number; dig?: number; bebe?: number; shirt?: string; flip?: number; pala?: boolean}> = ({x, y, k = 1, dig = 0, bebe = 0, shirt = '#4F6F8F', flip = 1, pala = true}) => {
  const hx = 34;
  const hy = -250 - 92 * (1 - dig);
  const rx = lerp(hx + 14, 24, bebe), ry = lerp(hy + 10, -352, bebe);
  return (
    <g transform={`translate(${x} ${y}) scale(${k * flip} ${k})`}>
      <ellipse cy="4" rx="80" ry="13" fill="rgba(60,35,10,.3)" />
      <path d="M-26 -180 L-34 -10 M26 -180 L30 -10" stroke="#E4D6B2" strokeWidth="32" strokeLinecap="round" fill="none" />
      <ellipse cx="-36" cy="-6" rx="20" ry="9" fill="#B98660" />
      <ellipse cx="32" cy="-6" rx="20" ry="9" fill="#B98660" />
      <path d="M-50 -332 Q0 -348 50 -332 L58 -170 L-58 -170Z" fill={shirt} />
      <path d="M-30 -330 Q-36 -250 -28 -176" stroke="rgba(255,255,255,.22)" strokeWidth="8" fill="none" strokeLinecap="round" />
      <rect x="-58" y="-188" width="116" height="14" rx="6" fill="#8C6B3E" />
      <path d={`M-46 -318 Q-70 ${(-318 + hy) / 2 + 24} ${hx - 10} ${hy}`} stroke={shirt} strokeWidth="30" strokeLinecap="round" fill="none" />
      <path d={`M46 -318 Q${lerp(80, 70, bebe)} ${(-318 + ry) / 2 + 20} ${rx} ${ry}`} stroke={shirt} strokeWidth="30" strokeLinecap="round" fill="none" />
      <circle cx={hx - 10} cy={hy} r="15" fill="#B98660" />
      {pala && bebe < 0.5 && <Pala x={hx} y={hy + 300} rot={6 * (1 - dig)} k={0.55} len={700} />}
      <circle cx={rx} cy={ry} r="15" fill="#B98660" />
      {bebe < 0.05 ? (
        <g><path d="M30 -330 Q70 -250 56 -170" stroke="#8C6B3E" strokeWidth="5" fill="none" /><ellipse cx="60" cy="-168" rx="22" ry="30" fill="#A07A44" stroke="#6E5230" strokeWidth="4" /></g>
      ) : (
        <g transform={`translate(${rx} ${ry}) rotate(${lerp(0, -105, bebe)})`}><ellipse cx="0" cy="-22" rx="22" ry="30" fill="#A07A44" stroke="#6E5230" strokeWidth="4" /><rect x="-7" y="-60" width="14" height="14" fill="#6E5230" /></g>
      )}
      <g transform={`rotate(${-16 * bebe} 0 -330)`}>
        <rect x="-13" y="-352" width="26" height="28" fill="#B98660" />
        <circle cx="0" cy="-374" r="34" fill="url(#gPiel)" />
        {[-12, 12].map((a) => (<g key={a}><ellipse cx={a} cy="-374" rx="4.5" ry={bebe > 0.6 ? 0.8 : 4} fill="#2A1A10" />{bebe < 0.6 && <circle cx={a + 1.6} cy="-375.5" r="1.5" fill="#fff" />}</g>))}
        <path d="M-8 -358 Q0 -354 8 -358" stroke="#7A4A33" strokeWidth="2.5" fill="none" />
        <path d="M-104 -398 Q0 -424 104 -398 Q62 -378 0 -382 Q-62 -378 -104 -398Z" fill="#D9B35C" stroke="#9C7A32" strokeWidth="3" />
        <path d="M-54 -404 L0 -486 L54 -404Z" fill="#E6C26C" stroke="#9C7A32" strokeWidth="3" />
        <path d="M-30 -412 L-6 -470 M0 -412 L0 -480 M30 -412 L8 -470" stroke="#B8923F" strokeWidth="3" fill="none" />
      </g>
    </g>
  );
};

// ---------- caballo de barro (de perfil) y carro ----------
const Caballo: React.FC<{x: number; y: number; k: number; s: number; ph?: number}> = ({x, y, k, s, ph = 0}) => {
  const b = Math.sin(s * 2.4 + ph) * 4;
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <ellipse cy="4" rx="150" ry="16" fill="rgba(40,25,10,.3)" />
      <path d="M-96 -152 L-86 -84 L-98 -6 M96 -152 L106 -84 L100 -6" stroke="#6F604B" strokeWidth="26" strokeLinecap="round" strokeLinejoin="round" fill="none" />
      <path d="M-70 -152 L-60 -84 L-72 -6 M70 -152 L80 -84 L74 -6" stroke="#8C7B64" strokeWidth="26" strokeLinecap="round" strokeLinejoin="round" fill="none" />
      <path d="M-126 -206 Q-168 -150 -150 -60" stroke="#5E513F" strokeWidth="16" strokeLinecap="round" fill="none" />
      <ellipse cx="0" cy="-196" rx="134" ry="62" fill="url(#gBarro)" />
      <path d="M-70 -236 Q-20 -250 40 -240" stroke="rgba(255,248,225,.4)" strokeWidth="8" fill="none" strokeLinecap="round" />
      <g transform={`translate(0 ${b})`}>
        <path d="M70 -230 Q128 -270 150 -346 L196 -340 Q160 -250 118 -170Z" fill="url(#gBarro)" />
        <path d="M150 -346 Q150 -300 120 -240" stroke="#4E4333" strokeWidth="10" fill="none" />
        <ellipse cx="184" cy="-338" rx="58" ry="28" transform="rotate(26 184 -338)" fill="url(#gBarro)" />
        <path d="M150 -372 L154 -400 L168 -372Z" fill="#6F604B" />
        <ellipse cx="190" cy="-346" rx="6" ry="5" fill="#241A12" />
        <circle cx="191.8" cy="-347.8" r="1.8" fill="#fff" />
      </g>
    </g>
  );
};
const Carro: React.FC<{x: number; y: number; k: number}> = ({x, y, k}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <ellipse cy="4" rx="150" ry="14" fill="rgba(40,25,10,.3)" />
    <path d="M60 -120 L250 -170" stroke="#5E513F" strokeWidth="12" strokeLinecap="round" />
    <rect x="-84" y="-250" width="170" height="104" rx="10" fill="url(#gBarro)" stroke="#5E513F" strokeWidth="5" />
    <path d="M-60 -250 L-60 -330 M60 -250 L60 -330" stroke="#6F604B" strokeWidth="10" />
    <path d="M-84 -330 H84 L70 -300 H-70Z" fill="#8C7B64" stroke="#5E513F" strokeWidth="4" />
    <circle cx="0" cy="-76" r="76" fill="none" stroke="#6F604B" strokeWidth="14" />
    {[0, 1, 2, 3, 4, 5].map((i) => <line key={i} x1="0" y1="-76" x2={Math.cos(i * 0.5236) * 72} y2={-76 + Math.sin(i * 0.5236) * 72} stroke="#8C7B64" strokeWidth="7" />)}
    {[0, 1, 2, 3, 4, 5].map((i) => <line key={'b' + i} x1="0" y1="-76" x2={-Math.cos(i * 0.5236) * 72} y2={-76 - Math.sin(i * 0.5236) * 72} stroke="#8C7B64" strokeWidth="7" />)}
    <circle cx="0" cy="-76" r="14" fill="url(#gBronce)" />
  </g>
);

const star = (a: number) => `M0 ${-a}L${a * 0.16} ${-a * 0.16}L${a} 0L${a * 0.16} ${a * 0.16}L0 ${a}L${-a * 0.16} ${a * 0.16}L${-a} 0L${-a * 0.16} ${-a * 0.16}Z`;

// ---------- 0. El hueco con ojos (E1) ----------
const Hueco: React.FC = () => {
  const {s} = useS();
  const cx = 540, cy = 1010;
  const tEj = en('ejército');
  const open = eo(s, 0, 1.1);
  const rx = 165 + 120 * open, ry = 84 + 64 * open;
  const z = 1 + 0.4 * ez(s, 0, E(2) + 0.5);
  const kf = [0, 0.2, 0.55, 1.1, 1.9];
  const px = interpolate(s, kf, [492, 500, 470, 400, 300], clamp);
  const py = interpolate(s, kf, [1040, 1074, 1000, 700, -200], clamp);
  const pr = interpolate(s, kf, [18, 18, 6, -22, -35], clamp);
  const caras = Array.from({length: 14}).map((_, i) => {
    const fx = cx + (h(i * 2 + 1) * 2 - 1) * rx * 0.72;
    const fy = cy + (h(i * 2 + 2) * 2 - 1) * ry * 0.6 + ry * 0.1;
    const ti = i < 5 ? i * 0.07 : tEj + (i - 5) * 0.05;
    return {fx, fy, sc: 0.5 + 0.55 * ((fy - (cy - ry)) / (2 * ry)), a: i < 5 ? 1 : pop(s, ti, 0.3), i};
  }).sort((a, b) => a.fy - b.fy);
  return (
    <AbsoluteFill>
      <Svg>
        <g transform={`translate(${cx} ${cy}) scale(${z}) translate(${-cx} ${-cy})`}>
          <rect x="-200" y="-200" width="1480" height="2320" fill="url(#gTierra)" />
          <circle cx="260" cy="420" r="520" fill="url(#gHalo)" opacity=".7" />
          {Array.from({length: 18}).map((_, i) => {
            const a = (i / 18) * Math.PI * 2 + h(i) * 0.3;
            const pts = [0, 1, 2, 3].map((n) => {
              const rr = (rx + 20 + n * 190) * (0.9 + h(i * 7 + n) * 0.3);
              return `${cx + Math.cos(a + (h(i + n * 5) - 0.5) * 0.25) * rr * 1.7},${cy + Math.sin(a + (h(i + n * 5) - 0.5) * 0.25) * rr * 0.95}`;
            });
            return <polyline key={i} points={pts.join(' ')} fill="none" stroke="#6E4F2A" strokeWidth={9 - (i % 4) * 1.5} strokeLinecap="round" strokeLinejoin="round" opacity=".7" />;
          })}
          {Array.from({length: 40}).map((_, i) => <circle key={'g' + i} cx={h(i * 3) * 1080} cy={h(i * 5 + 1) * 1920} r={3 + h(i) * 6} fill={i % 2 ? '#B08549' : '#E7CC93'} opacity=".5" />)}
          <ellipse cx={cx} cy={cy + 14} rx={rx + 38} ry={ry + 24} fill="#9B7742" />
          <ellipse cx={cx - 12} cy={cy - 6} rx={rx + 22} ry={ry + 14} fill="#7C5B30" />
          <ellipse cx={cx} cy={cy} rx={rx} ry={ry} fill="url(#gHoyo)" />
          <clipPath id="cHoyo"><ellipse cx={cx} cy={cy} rx={rx} ry={ry} /></clipPath>
          <g clipPath="url(#cHoyo)">
            {caras.map((c) => (
              <g key={c.i} transform={`translate(${c.fx} ${c.fy}) scale(${c.sc * c.a})`}>
                <ellipse rx="50" ry="58" fill="url(#gBarro)" stroke="#2F261B" strokeWidth="3" />
                <ellipse rx="50" ry="58" fill="rgba(10,5,2,.3)" />
                {[-17, 17].map((a) => (<g key={a}><ellipse cx={a} cy="-6" rx="9" ry="6.5" fill="#1B120A" /><circle cx={a + 2.4} cy="-8" r="2.4" fill="#fff" /></g>))}
                <path d="M-28 -22 Q-17 -28 -6 -22 M6 -22 Q17 -28 28 -22" stroke="#3B3126" strokeWidth="4" fill="none" />
                <path d="M0 -4 L5 16 L-4 16" stroke="#3B3126" strokeOpacity=".55" strokeWidth="3" fill="none" />
                <path d="M-12 32 Q0 36 12 32" stroke="#3B3126" strokeWidth="3" fill="none" />
              </g>
            ))}
          </g>
          {Array.from({length: 18}).map((_, i) => {
            const u = s - (0.4 + i * 0.03);
            if (u < 0 || u > 1.3) return null;
            const x = cx + (h(i) * 2 - 1) * rx * 0.8 + (h(i + 9) * 2 - 1) * 170 * u;
            const y = cy - (260 + h(i + 3) * 280) * u + 1100 * u * u;
            return <circle key={'p' + i} cx={x} cy={y} r={6 + h(i + 5) * 11} fill={i % 2 ? '#B08549' : '#8E6A3A'} opacity={1 - u / 1.3} />;
          })}
          <Pala x={px} y={py} rot={pr} k={1} len={760} />
          {s > 0.5 && s < 1.3 && <ellipse cx={px - 6} cy={py - 30} rx="60" ry="28" fill="#A47E49" opacity={1 - ez(s, 1.0, 1.3)} />}
        </g>
      </Svg>
      <Brillo x={540} y={1010} r={380} t0={tEj} color="rgba(255,226,150,.5)" />
      <Ondas x={540} y={1010} t0={tEj} color="#FFE6A0" radio={520} />
      <Acabado sem={1} />
    </AbsoluteFill>
  );
};

// ---------- 1. El campo seco (E2, E3 y el final E13/E14) ----------
const LANES = [{y: 1520, k: 0.62}, {y: 1330, k: 0.5}, {y: 1170, k: 0.4}, {y: 1040, k: 0.33}, {y: 940, k: 0.27}, {y: 860, k: 0.22}];
const tCab = en('caballos');
const filas = (s: number, pan: number, op: {alfa?: (r: number) => number; caballos?: boolean} = {}) => {
  const out: React.ReactNode[] = [];
  for (let r = 5; r >= 0; r--) {
    const L = LANES[r];
    const par = L.k / 0.62;
    const off = pan * par;
    const sp = 250 * L.k;
    const al = op.alfa ? op.alfa(r) : 1;
    if (al <= 0.01) continue;
    const items: React.ReactNode[] = [];
    const i0 = Math.max(0, Math.floor((off - 140 + 300) / sp));
    for (let i = i0; i < i0 + 40; i++) {
      const X = -300 + i * sp + (r % 2) * sp * 0.5;
      const sx = X - off;
      if (sx < -140) continue;
      if (sx > 1220) break;
      if (op.caballos && r === 1 && X > 520 && X < 1330 && s >= tCab - 0.05) continue;
      const lanza = (r === 0 && i % 4 === 0) || (r === 2 && i % 3 === 1);
      items.push(<Soldado key={i} x={sx} y={L.y} k={L.k} det={L.k >= 0.4} lanza={lanza} />);
      if (lanza && s > en('armas') - 0.1) {
        const tg = en('armas') + (i % 5) * 0.08, tb = en('bronce') + (i % 4) * 0.06;
        const a = Math.max(0, 1 - Math.abs(s - tg) * 2.6) * 0.8 + Math.max(0, 1 - Math.abs(s - tb) * 3) * 1.3;
        if (a > 0.02) items.push(<path key={'s' + i} transform={`translate(${sx + 81.5 * L.k} ${L.y - 570 * L.k})`} d={star(46 * L.k * a + 4)} fill="#FFF3B8" />);
      }
    }
    out.push(
      <g key={r} opacity={al}>
        <rect x="-10" y={L.y - 34 * L.k} width="1100" height={48 * L.k} fill={r % 2 ? '#7B6447' : '#6B563C'} />
        <rect x="-10" y={L.y + 14 * L.k} width="1100" height={22 * L.k} fill="#9A8262" />
        <rect x="-10" y={L.y + 14 * L.k} width="1100" height={4 * L.k} fill="#B79F7C" />
        {items}
        {op.caballos && r === 1 && (
          <g>
            {s >= en('carros') - 0.05 && <g transform={`translate(0 ${(1 - pop(s, en('carros'), 0.35)) * 60})`} opacity={pop(s, en('carros'), 0.2)}><Carro x={620 - pan * 0.8} y={L.y} k={0.6} /></g>}
            {[0, 1, 2].map((j) => s >= tCab - 0.05 + j * 0.12 && <g key={j} opacity={pop(s, tCab + j * 0.12, 0.2)}><Caballo x={880 + j * 190 - pan * 0.8} y={L.y - (1 - pop(s, tCab + j * 0.12, 0.35)) * 40} k={0.6} s={s} ph={j * 1.3} /></g>)}
          </g>
        )}
      </g>,
    );
  }
  return out;
};

const China = 'M20 70 L45 55 L60 30 L85 38 L100 15 L120 28 L150 22 L175 40 L165 62 L185 75 L170 95 L150 98 L140 120 L115 118 L100 140 L75 135 L62 112 L40 108 L25 90Z';

const Campo: React.FC<{fin?: boolean}> = ({fin: esFin = false}) => {
  const {s} = useS();
  const tE3 = E(3);
  const z = esFin
    ? 1.05 + 0.45 * ez(s, E(13) + 0.2, E(14) + 0.6) + 0.06 * ez(s, E(14) + 0.6, DUR)
    : 1 + 0.04 * ez(s, E(2), tE3) + 0.8 * ez(s, tE3, tE3 + 1.8) + 0.08 * ez(s, tE3 + 1.8, E(4));
  const th = esFin ? 0 : 75 * ez(s, tE3 + 0.4, E(4));
  const a = (th * Math.PI) / 180;
  const P = (u: number, v: number) => {
    const uu = u * Math.cos(a) - v * Math.sin(a), vv = u * Math.sin(a) + v * Math.cos(a);
    return {x: 540 + uu, y: 1300 + vv * 0.4, d: vv};
  };
  const sequia = ez(s, en('primavera'), en('sequía') + 0.6);
  const R = esFin ? 190 : 46 + 144 * ez(s, tE3 + 0.5, en('pozo', 2) + 0.9);
  const rev = esFin ? ez(s, E(14), E(14) + 1.7) : 0;
  const arrive = ez(s, tE3 - 0.1, tE3 + 1.5);
  const Rr = 330 + 640 * (1 - arrive);
  const P0 = tE3 > 0 ? en('cavaban') + 0.05 : 0;
  const per = 1.46;
  const digOf = (off: number) => 0.5 + 0.5 * Math.cos(((s - P0 + off * per) / per) * Math.PI * 2);
  // gente (u,v, escala fija, fase)
  const gente = esFin
    ? [
        {u: 250, v: 60, ph: 0, bebe: ez(s, en('tenían') - 0.5, en('sed')), shirt: '#4F6F8F', flip: -1},
        {u: -250, v: 200, ph: 0.3, bebe: 0, shirt: '#B5603C', flip: 1},
        {u: 40, v: -230, ph: 0.6, bebe: 0, shirt: '#6D8B5A', flip: 1},
      ]
    : [
        {u: Rr * Math.cos(1.5708), v: Rr * Math.sin(1.5708), ph: 0, bebe: 0, shirt: '#4F6F8F', flip: 1},
        {u: Rr * Math.cos(3.75), v: Rr * Math.sin(3.75), ph: 0.37, bebe: 0, shirt: '#B5603C', flip: 1},
        {u: Rr * Math.cos(5.85), v: Rr * Math.sin(5.85), ph: 0.7, bebe: 0, shirt: '#6D8B5A', flip: -1},
      ];
  const draw: {d: number; el: React.ReactNode}[] = [];
  const mound = P(-250, -140);
  draw.push({d: mound.d, el: (
    <g key="mound">
      <ellipse cx={mound.x} cy={mound.y + 8} rx={(110 + R * 0.55) } ry={(34 + R * 0.2)} fill="#9A7440" />
      <ellipse cx={mound.x - 14} cy={mound.y - 6} rx={(96 + R * 0.5)} ry={(28 + R * 0.17)} fill="url(#gTierra)" />
      <path d={`M${mound.x - 80} ${mound.y - 10} Q${mound.x - 20} ${mound.y - 40} ${mound.x + 40} ${mound.y - 14}`} stroke="rgba(255,240,200,.45)" strokeWidth="8" fill="none" strokeLinecap="round" />
    </g>
  )});
  gente.forEach((g, i) => {
    const q = P(g.u, g.v);
    const kk = 0.78 + 0.0007 * q.d;
    draw.push({d: q.d, el: <Campesino key={'c' + i} x={q.x} y={q.y} k={kk} dig={esFin ? 0.45 : digOf(g.ph)} bebe={g.bebe} shirt={g.shirt} flip={g.flip} pala={!esFin} />});
  });
  if (esFin) {
    const q = P(-300, 90);
    draw.push({d: q.d, el: <g key="pala"><ellipse cx={q.x} cy={q.y + 4} rx="46" ry="12" fill="rgba(60,35,10,.35)" /><Pala x={q.x} y={q.y + 10} rot={-8 + Math.sin(s * 1.3) * 1} k={0.62} len={760} /></g>});
  }
  draw.sort((p, q) => p.d - q.d);
  const hit1 = P0, hit2 = P0 + per;
  const tufts = Array.from({length: 18}).map((_, i) => {
    const q = P((h(i * 3 + 1) * 2 - 1) * 760, (h(i * 5 + 2) * 2 - 1) * 520);
    return {q, i};
  }).sort((p, q) => p.q.d - q.q.d);
  const hutT = en('aldea');
  return (
    <AbsoluteFill>
      <Svg>
        <g transform={`translate(540 1300) scale(${z}) translate(-540 -1300)`}>
          <rect x="-700" y="-1200" width="2480" height="2190" fill="url(#gSky)" />
          <circle cx="830" cy="520" r="420" fill="url(#gHalo)" />
          <circle cx="830" cy="520" r={112 + Math.sin(s * 1.6) * 3} fill="#FFF6D6" />
          <path d="M-700 990 Q-300 930 100 975 T700 960 T1300 985 L1300 1010 L-700 1010Z" fill="#D2A865" opacity=".8" />
          <path d="M-700 1000 Q-200 960 300 992 T1000 985 T1700 1000 L1700 1020 L-700 1020Z" fill="#BE9453" />
          {hutT > 0 && [0, 1, 2, 3].map((i) => {
            const sc = pop(s, hutT + i * 0.1, 0.4);
            return (
              <g key={i} transform={`translate(${130 + i * 110} 1004) scale(${sc})`}>
                <rect x="-38" y="-46" width="76" height="46" fill="#D8B77F" /><rect x="-44" y="-56" width="88" height="14" fill="#9C7A47" /><rect x="-9" y="-30" width="18" height="30" fill="#4B331D" />
              </g>
            );
          })}
          {s > hutT && Array.from({length: 4}).map((_, i) => {
            const u = (s - hutT - i * 0.5) % 2;
            return <circle key={'h' + i} cx={150 + Math.sin(u * 3 + i) * 12 + u * 14} cy={950 - u * 60} r={6 + u * 7} fill="rgba(240,230,210,.6)" opacity={Math.max(0, 1 - u / 2)} />;
          })}
          <rect x="-700" y="990" width="2480" height="1200" fill="url(#gTierra)" />
          {Array.from({length: 12}).map((_, i) => {
            const pts = [0, 1, 2, 3, 4].map((n) => { const q = P(Math.cos(i * 0.62 + 0.2) * (230 + n * 210) * (0.9 + h(i * 7 + n) * 0.25), Math.sin(i * 0.62 + 0.2) * (230 + n * 210) * (0.9 + h(i * 5 + n) * 0.25)); return `${q.x},${q.y}`; });
            return <polyline key={i} points={pts.join(' ')} fill="none" stroke="#6E4F2A" strokeWidth={(2.5 + (i % 3)) * (1 + sequia * 1.1)} strokeLinecap="round" strokeLinejoin="round" opacity=".75" />;
          })}
          {tufts.map(({q, i}) => (
            <path key={'t' + i} transform={`translate(${q.x} ${q.y}) scale(${0.7 + q.d * 0.0007})`} d="M0 0 q-8 -34 -2 -62 M0 0 q10 -26 14 -50 M0 0 q-16 -20 -22 -44" stroke="#8A6B2F" strokeWidth="4" fill="none" strokeLinecap="round" />
          ))}
          {esFin && (
            <g opacity={rev}>
              <rect x="-700" y="1000" width="2480" height="1200" fill="#2A1C10" />
              <rect x="-700" y="1000" width="2480" height="1200" fill="rgba(22,36,64,.35)" />
            </g>
          )}
          {esFin && <g>{filas(s, 0, {alfa: (r) => sm(rev * 1.1 - 0.05 * r - 0.1 + 0.2 * (5 - r) * 0.1) * 0.9 * rev})}</g>}
          {esFin && <rect x="-700" y="1000" width="2480" height="1200" fill="url(#gTierra)" opacity={1 - 0.74 * rev} />}
          {esFin && Array.from({length: 12}).map((_, i) => {
            const pts = [0, 1, 2, 3, 4].map((n) => { const q = P(Math.cos(i * 0.62 + 0.2) * (230 + n * 210) * (0.9 + h(i * 7 + n) * 0.25), Math.sin(i * 0.62 + 0.2) * (230 + n * 210) * (0.9 + h(i * 5 + n) * 0.25)); return `${q.x},${q.y}`; });
            return <polyline key={'k' + i} points={pts.join(' ')} fill="none" stroke="#6E4F2A" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" opacity=".7" />;
          })}
          <ellipse cx="540" cy="1304" rx={R + 22} ry={R * 0.4 + 10} fill="#9A7440" />
          <ellipse cx="540" cy="1300" rx={R} ry={R * 0.4} fill="url(#gHoyo)" />
          <ellipse cx="540" cy="1300" rx={R} ry={R * 0.4} fill="none" stroke="rgba(255,240,200,.5)" strokeWidth="4" />
          {draw.map((q) => q.el)}
          {!esFin && [hit1, hit2].map((t, i) => s > t && s < t + 0.7 && <ellipse key={i} cx={540 + (i ? -120 : 90)} cy={1330} rx={30 + (s - t) * 120} ry={10 + (s - t) * 38} fill="rgba(210,180,120,.5)" opacity={1 - (s - t) / 0.7} />)}
          {!esFin && s > en('agua') - 0.1 && s < en('agua') + 1.4 && (
            <g transform={`translate(540 ${1180 - eo(s, en('agua'), en('agua') + 0.8) * 60}) scale(${pop(s, en('agua'), 0.3) * (1 - ez(s, en('agua') + 0.8, en('agua') + 1.3) * 0.9)})`} opacity={1 - ez(s, en('agua') + 0.8, en('agua') + 1.4)}>
              <path d="M0 -60 Q38 -6 36 22 Q34 56 0 56 Q-34 56 -36 22 Q-38 -6 0 -60Z" fill="#6FB6E8" stroke="#2F6FA0" strokeWidth="4" />
              <path d="M-14 -4 Q-20 18 -8 34" stroke="rgba(255,255,255,.8)" strokeWidth="6" fill="none" strokeLinecap="round" />
            </g>
          )}
        </g>
      </Svg>
      {!esFin && s < tE3 + 0.8 && (
        <>
          <Chip texto="1974" x={540} y={470} t0={en('primavera')} t1={tE3 - 0.1} />
          <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0}}>
            <g transform={`translate(540 760) scale(${pop(s, en('centro'), 0.35) * (1 - ez(s, tE3 - 0.1, tE3 + 0.5))})`}>
              <rect x="-210" y="-165" width="420" height="330" rx="26" fill="rgba(10,14,24,.82)" stroke="#E7FF00" strokeWidth="4" />
              <g transform="translate(-170 -136) scale(1.7)">
                <path d={China} fill="#3D5A3D" stroke="#E7FF00" strokeWidth="2.5" strokeLinejoin="round" />
                <circle cx="100" cy="80" r="7" fill="#FF5A4A" />
                {[0, 0.4].map((d, i) => { const u = ((s - en('centro') - d) % 1.1 + 1.1) % 1.1; return <circle key={i} cx="100" cy="80" r={7 + u * 26} fill="none" stroke="#FF5A4A" strokeWidth="2.5" opacity={1 - u / 1.1} />; })}
