};

// ---------- 2. Fondo del pozo (E4, E5, E6 hasta «filas») ----------
const FLOOR = 1500, SURF = 1010;
const XS = [540, 1100, 1660];
const NICHO: [number, number][] = [[350, 730], [910, 1290], [1470, 2200]];
const Pozo: React.FC = () => {
  const {s} = useS();
  const r = [en('cuerpo'), en('otro', 1), en('otro', 2)];
  const tHead = en('cabeza'), tHit = en('duro');
  const cy = -900 * (1 - ez(s, E(4) - 0.1, tHit - 0.25));
  const dip = (i: number) => ez(s, r[i], r[i] + 0.55);
  const pan = 560 * ez(s, r[0] + 0.5, r[0] + 0.85) + 560 * ez(s, r[1] + 0.4, r[1] + 0.7) - 410 * ez(s, E(6) + 0.1, E(6) + 1.3);
  const zz = 1 - 0.38 * ez(s, E(6) + 0.1, E(6) + 1.3);
  const surf = (x: number) => {
    let y = SURF;
    NICHO.forEach(([a, b], i) => {
      const d = x < a ? a - x : x > b ? x - b : 0;
      const w = 1 - Math.min(1, d / 60);
      y += dip(i) * (FLOOR - SURF) * w * w * (3 - 2 * w);
    });
    return y;
  };
  const pts: string[] = [];
  for (let x = -700; x <= 2900; x += 20) pts.push(`${x},${surf(x).toFixed(1)}`);
  const sol = [0, 1, 2].map((i) => (i === 0 ? 130 * (1 - ez(s, tHead - 0.15, tHead + 0.3)) : 130 * (1 - ez(s, r[i] - 0.35, r[i] - 0.05))));
  const ojos = [0, 1, 2].map((i) => (i === 0 ? ez(s, r[0] + 0.2, r[0] + 0.5) : ez(s, r[i] + 0.2, r[i] + 0.5)));
  const clods = (t0: number, x0: number, y0: number, n: number, seed: number) =>
    Array.from({length: n}).map((_, i) => {
      const u = s - t0;
      if (u < 0 || u > 1.3) return null;
      const x = x0 + (h(seed + i) * 2 - 1) * 280 * u;
      const y = y0 - (240 + h(seed + i + 40) * 320) * u + 1050 * u * u;
      return <rect key={seed + '_' + i} x={x} y={y} width={12 + h(seed + i + 9) * 16} height={10 + h(seed + i + 3) * 12} rx="4" transform={`rotate(${u * 320 * (h(seed + i) - 0.5)} ${x} ${y})`} fill={i % 2 ? '#8E6A3A' : '#B08549'} opacity={1 - u / 1.3} />;
    });
  const kP = [0, 10.0, 11.78, 12.05, 12.75, 13.3, 15.0, 15.5];
  const tPx = interpolate(s, kP, [545, 545, 548, 548, 470, 380, 380, 380], clamp);
  const tPy = interpolate(s, [10.0, 11.78, 12.05, 12.75, 13.3, 15.0, 15.5], [-300, 876, 850, 760, 900, 900, -400], {...clamp, easing: Easing.inOut(Easing.quad)});
  const dg = s > 13.4 && s < 14.95 ? 80 * (0.5 - 0.5 * Math.cos(((s - 13.4) / 0.75) * Math.PI * 2)) : 0;
  const palaY = tHit > 0 ? tPy + dg : 0;
  const caidas = sacudida(s, [tHit], 12);
  return (
    <AbsoluteFill>
      <Svg>
        <g transform={`translate(${caidas.x} ${caidas.y}) translate(0 ${-cy}) translate(540 1100) scale(${zz}) translate(${-(540 + pan)} -1100)`}>
          <rect x="-900" y="-1500" width="3800" height="3700" fill="url(#gPared)" />
          {Array.from({length: 50}).map((_, i) => <path key={i} d={`M${-800 + (i % 10) * 380} ${-900 + Math.floor(i / 10) * 520 + h(i) * 200} q90 -30 190 ${10 + h(i * 3) * 30} t180 -10`} stroke="#3B2916" strokeWidth={5 + h(i + 2) * 5} fill="none" opacity=".5" />)}
          {Array.from({length: 46}).map((_, i) => <ellipse key={'s' + i} cx={-800 + h(i * 7) * 3500} cy={-1000 + h(i * 11 + 1) * 2600} rx={10 + h(i) * 22} ry={7 + h(i + 5) * 14} fill={i % 2 ? '#A8855A' : '#5B4228'} opacity=".7" />)}
          <ellipse cx="540" cy="-760" rx="460" ry="150" fill="#6B4D2B" />
          <ellipse cx="540" cy="-766" rx="420" ry="128" fill="url(#gSky)" />
          {[380, 560, 730].map((hx, i) => (
            <g key={i} transform={`translate(${hx + Math.sin(s * 0.7 + i) * 6} ${-720 + (i % 2) * 14})`}>
              <circle r="22" fill="#2E2012" /><path d="M-60 -16 L0 -64 L60 -16Z" fill="#3A2A18" />
            </g>
          ))}
          <polygon points="250,-700 830,-700 1500,1500 -420,1500" fill="url(#gLuz)" />
          <polygon points="440,-700 640,-700 1000,1500 100,1500" fill="url(#gLuz)" opacity=".7" />
          {XS.map((x, i) => <Soldado key={i} x={x} y={FLOOR + sol[i]} k={1.36} ojos={ojos[i]} />)}
          <polygon points={`${pts.join(' ')} 2900,2300 -700,2300`} fill="url(#gTierraO)" />
          <polyline points={pts.join(' ')} fill="none" stroke="#D6B47A" strokeWidth="7" strokeLinejoin="round" />
          {Array.from({length: 60}).map((_, i) => { const x = -600 + h(i * 3) * 3300; return <circle key={'q' + i} cx={x} cy={Math.max(surf(x) + 30, 1060) + h(i * 5) * 700} r={4 + h(i) * 9} fill={i % 2 ? '#C9A46A' : '#4A3420'} opacity=".6" />; })}
          {clods(tHit, 545, 880, 9, 1)}
          {XS.map((x, i) => clods(r[i] + 0.05, x, SURF, 10, 20 + i * 30))}
          {Array.from({length: 10}).map((_, i) => clods(13.3 + i * 0.16, 400, 1000, 3, 100 + i * 7))}
          <Campesino x={interpolate(s, [en('tamaño') - 0.2, en('tamaño') + 0.8], [2500, 2020], {...clamp, easing: Easing.out(Easing.cubic)})} y={FLOOR} k={1.2} dig={0.3} pala={false} />
          <Pala x={tPx} y={palaY} rot={interpolate(s, [12.05, 12.75, 13.3], [2, -6, -8], clamp)} k={1.3} len={1700} />
        </g>
      </Svg>
      <Brillo x={540} y={930} r={300} t0={tHead} color="rgba(255,226,150,.45)" />
      <Acabado sem={3} luz="rgba(255,240,200,.18)" sombra="rgba(15,8,2,.7)" />
    </AbsoluteFill>
  );
};

// ---------- 3. El foso con el ejército (E6 desde «filas», E7 y E8) ----------
const LAY = ['#8D6E46', '#B38C56', '#6F5334', '#C9A56C', '#5C452E'];
const Foso: React.FC = () => {
  const {s} = useS();
  const tL = (i: number) => E(8) + 0.25 + i * 0.45;
  const pan = 560 * ez(s, E(7) + 0.1, E(8) + 0.2);
  const ty = 950 * ez(s, E(8) + 0.3, E(9) + 1.3);
  const zf = 1 + 0.12 * (1 - ez(s, en('filas'), E(7))) ;
  const sh = sacudida(s, [0, 1, 2, 3, 4].map((i) => tL(i) + 0.5), 8);
  return (
    <AbsoluteFill>
      <Svg>
        <g transform={`translate(${sh.x} ${sh.y + ty}) translate(540 1100) scale(${zf}) translate(-540 -1100)`}>
          <rect x="-700" y="-2200" width="2480" height="3000" fill="#CFB68A" />
          <rect x="-700" y="-300" width="2480" height="1100" fill="#BDA070" />
          <circle cx="260" cy="300" r="560" fill="url(#gHalo)" opacity=".5" />
          <rect x="-700" y="780" width="2480" height="1400" fill="#6F5A3F" />
