const colAt = (y: number) => (y < 880 ? '#E2B089' : y < 1150 ? '#BE3A2E' : y < 1440 ? '#3D8D5B' : '#2E6FB7');
const NP = 60;
const parches = Array.from({length: NP}).map((_, i) => {
  const gx = i % 6, gy = Math.floor(i / 6);
