            const pts = Array.from({length: 7}).map((_, n) => `${c.px + Math.cos(n * 0.8976 + c.i) * c.r * k * (0.78 + 0.45 * h(c.i * 11 + n))},${c.py + Math.sin(n * 0.8976 + c.i) * c.r * k * (0.78 + 0.45 * h(c.i * 11 + n))}`).join(' ');
