          return <path key={i} d={`M${x} ${y} q70 -30 150 0 q40 14 70 -8`} stroke="rgba(235,245,250,.7)" strokeWidth="6" fill="none" strokeLinecap="round" opacity={0.8 * viento + 0.1} />;
        })}
